(() => {
 'use strict';
 const artists=window.ARTISTS;
 const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const artDialog=$('#art-dialog'),photoDialog=$('#photo-dialog');let activeArt=0,lastFocus;
 const notes={2:'В первой экспозиции в РГБМ «Обработка полей» находилась рядом с литературой по сельскому и лесному хозяйству. Стеллаж 20, правая сторона, секция 3, полка 3.',3:'В РГБМ работа была размещена в зале литературы по общественным и гуманитарным наукам: стеллаж 8, правая сторона, секция 2, полка 6.',8:'В первой экспозиции «Лягушонок» получил место в разделе о земноводных: стеллаж 19, левая сторона, секция 1, полка 4. В саратовском описании: холст, акрил, 14,8 × 21 см.',10:'В РГБМ «Красная книга» была размещена в разделе «Охрана живой природы». Стеллаж 26, полка 4.',15:'В РГБМ «Капитан» находился в зале редкой книги: шкаф слева, секция 2, полка 3.',16:'В РГБМ «Лунокот» оказался в «Музыкальном подвале», в разделе электронной музыки. В саратовском описании: холст, акрил, 21 × 29,7 см.',18:'В московском путеводителе эта работа соседствовала с книгами по ботанике: стеллаж 15, левая сторона, секция 1, полка 1. В саратовском описании: холст, акрил, 14,8 × 21 см.'};
 function renderArt(id){activeArt=(id+artists.length)%artists.length;const a=artists[activeArt];$('#dialog-title').textContent=a.name;$('#dialog-work').textContent='«'+a.title+'»';$('#dialog-image').src=a.image;$('#dialog-image').alt=a.name+'. '+a.title;$('#dialog-note').textContent=notes[activeArt]||'Работа из собрания проекта «Между книг». В каждом городе состав экспозиции и соседство произведений с книгами менялись.';$('#art-position').textContent=String(activeArt+1).padStart(2,'0')+' / '+artists.length;}
 function openDialog(d){lastFocus=document.activeElement;document.body.classList.add('modal-open');d.showModal();$('.dialog-close',d).focus();}
 function openArt(id){renderArt(id);openDialog(artDialog);}
 document.addEventListener('click',e=>{const art=e.target.closest('[data-art]');if(art){openArt(Number(art.dataset.art));return;}const photo=e.target.closest('[data-photo]');if(photo){$('#photo-image').src=photo.dataset.photo;$('#photo-image').alt=photo.dataset.caption;$('#photo-caption').textContent=photo.dataset.caption;openDialog(photoDialog);}});
 $$('.dialog-close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
 [artDialog,photoDialog].forEach(d=>{d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});d.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastFocus?.focus({preventScroll:true});});});
 $('#art-prev').addEventListener('click',()=>renderArt(activeArt-1));$('#art-next').addEventListener('click',()=>renderArt(activeArt+1));
 artDialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();renderArt(activeArt-1);}if(e.key==='ArrowRight'){e.preventDefault();renderArt(activeArt+1);}});
 const photos={ekb:[['assets/ekb-2.jpg','Екатеринбург. Произведения среди книг в библиотеке № 14, 2026'],['assets/ekb-1.jpg','Екатеринбург. Книжные стеллажи библиотеки № 14, 2026']],yak:[['assets/yak-1.jpg','Якутск. Поиск произведений на библиотечных полках, 2026. Фото: АРТ КУЛЬТУРА'],['assets/yak-2.jpg','Якутск. Знакомство с выставкой в библиотеке, 2026. Фото: АРТ КУЛЬТУРА'],['assets/yak-3.jpg','Якутск. Произведения среди книг, 2026. Фото: АРТ КУЛЬТУРА']],nn:[['assets/nn-3.webp','Нижний Новгород. Встреча в библиотеке гимназии № 53, 2026'],['assets/nn-2.webp','Нижний Новгород. Работы на стеллаже в гимназии № 53, 2026'],['assets/nn-1.webp','Нижний Новгород. Участники встречи у экспозиции, 2026']],mur:[['assets/mur-2.webp','Мурманск. Поиск картины среди книг в центре «БиблиоДвиж», 2026'],['assets/mur-1.webp','Мурманск. Зрители рассматривают произведение, 2026'],['assets/mur-3.webp','Мурманск. Посетительница находит работу с помощью путеводителя, 2026']],sar:[['assets/saratov-1.webp','Саратов. Картина «Доктор» рядом с книгой «Доктор Айболит», 2026'],['assets/saratov-2.webp','Саратов. «Красная книга» Даздрапермы Быковой на библиотечной полке, 2026'],['assets/saratov-3.webp','Саратов. Знакомство с произведением у книжного стеллажа, 2026']]};
 $$('.city-gallery').forEach(g=>{let n=0;const list=photos[g.dataset.gallery];function show(delta){n=(n+delta+list.length)%list.length;const [src,caption]=list[n],b=$('.city-image',g),im=$('img',b);im.src=src;im.alt=caption;$('.photo-counter',g).textContent=String(n+1).padStart(2,'0')+' / '+String(list.length).padStart(2,'0');}$('[data-gallery-prev]',g).addEventListener('click',()=>show(-1));$('[data-gallery-next]',g).addEventListener('click',()=>show(1));g.tabIndex=0;g.setAttribute('role','region');g.setAttribute('aria-label','Фотографии города: листайте стрелками или свайпом');g.addEventListener('keydown',e=>{if(e.target!==g)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();show(e.key==='ArrowRight'?1:-1);}});let touchStart;g.addEventListener('touchstart',e=>{const t=e.touches[0];touchStart={x:t.clientX,y:t.clientY};},{passive:true});g.addEventListener('touchend',e=>{if(!touchStart)return;const t=e.changedTouches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;touchStart=undefined;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))show(dx<0?1:-1);},{passive:true});g.addEventListener('touchcancel',()=>{touchStart=undefined;},{passive:true});});
 const steps=$$('.story-step'),sceneImages=$$('.scene-image'),cities=$$('.city'),routeLinks=$$('[data-route]'),sceneArt=[3,8,18];let activeScene=-1,activeCity=-1,scheduled=false;
 function setScene(n){if(n===activeScene)return;activeScene=n;sceneImages.forEach((im,i)=>{im.classList.toggle('active',i===n);im.setAttribute('aria-hidden',String(i!==n));});$('#scene-count').textContent='0'+(n+1)+' / 03';const a=artists[sceneArt[n]];$('#scene-caption').textContent=a.name+' · «'+a.title+'»';$('#scene-open').dataset.art=a.id;}
 function updateScroll(){scheduled=false;const vh=innerHeight,max=document.documentElement.scrollHeight-vh;$('#reading-progress').style.width=(max>0?scrollY/max*100:0)+'%';const aim=innerWidth<=760?vh*.70:vh*.55;let s=0;steps.forEach((el,i)=>{if(el.getBoundingClientRect().top<=aim)s=i;});setScene(s);let c=0;cities.forEach((el,i)=>{if(el.getBoundingClientRect().top<vh*.48)c=i;});if(c!==activeCity){activeCity=c;routeLinks.forEach((a,i)=>{a.classList.toggle('active',i===c);a.classList.toggle('visited',i<c);if(i===c)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current');});}}
 function requestScroll(){if(!scheduled){scheduled=true;requestAnimationFrame(updateScroll);}}
 addEventListener('scroll',requestScroll,{passive:true});addEventListener('resize',requestScroll,{passive:true});updateScroll();
})();
